namespace sct::ui {
class RamCompositionAccess {
    using Check=std::function<void(bool,const char*)>;
    static bool Wait(const std::function<bool()>& ready){const auto end=std::chrono::steady_clock::now()+std::chrono::seconds(12);for(;;){if(ready())return true;if(std::chrono::steady_clock::now()>=end)return false;services::PumpNativeTestMessages();Sleep(5);}}
    static void Key(EditorFrame* editor,UINT key){services::NeutralTestKeys();BYTE keys[256]{};keys[VK_CONTROL]=0x80;SetKeyboardState(keys);MSG message{};message.hwnd=editor->m_hWnd;message.message=WM_KEYDOWN;message.wParam=key;editor->PreTranslateMessage(&message);services::NeutralTestKeys();}
    static void Draw(EditorFrame* page,core::Tool tool,CPoint start,CPoint end){page->OnToolCommand(EditorToolFirst+static_cast<UINT>(tool));const auto a=page->ScreenRect({start.x,start.y,start.x,start.y}).TopLeft(),b=page->ScreenRect({end.x,end.y,end.x,end.y}).TopLeft();services::NeutralTestKeys();page->SendMessage(WM_LBUTTONDOWN,MK_LBUTTON,MAKELPARAM(a.x,a.y));page->SendMessage(WM_MOUSEMOVE,MK_LBUTTON,MAKELPARAM(b.x,b.y));page->SendMessage(WM_LBUTTONUP,0,MAKELPARAM(b.x,b.y));}
    static void Choice(EditorFrame* page,CComboBox& combo,const wchar_t* value,UINT id){int index=combo.FindStringExact(-1,value);if(index<0)index=combo.AddString(value);combo.SetCurSel(index);page->SendMessage(WM_COMMAND,MAKEWPARAM(id,CBN_SELCHANGE),reinterpret_cast<LPARAM>(combo.GetSafeHwnd()));}
public:static void Run(Check check,std::ofstream& log,const std::filesystem::path& dir){
    core::Image a,b,c;a.Create(320,220);b.Create(640,480);c.Create(1000,720);
    auto* first=EditorWorkspace::Open(core::Document(a).State(),L"",true);auto* second=EditorWorkspace::Open(core::Document(b).State(),L"",true);auto* third=EditorWorkspace::Open(core::Document(c).State(),L"",true);
    auto idle=[&]{for(auto* page:{first,second,third})if(page->WorkingForBuild())return false;return true;};check(Wait(idle),"RAM composition documents ready");
    check(first->DocumentName()!=second->DocumentName()&&second->DocumentName()!=third->DocumentName()&&first->path_.IsEmpty()&&second->path_.IsEmpty()&&third->path_.IsEmpty(),"unsaved RAM tabs have distinct session names without invented disk paths");
    EditorWorkspace::Current()->Activate(first);first->ZoomTo(1);auto* tabs=static_cast<CTabCtrl*>(first->ribbon_.GetDlgItem(RibbonTabs));tabs->SetCurSel(2);NMHDR header{tabs->GetSafeHwnd(),RibbonTabs,TCN_SELCHANGE};first->ribbon_.SendMessage(WM_NOTIFY,RibbonTabs,reinterpret_cast<LPARAM>(&header));
    bool customColorVisible=false;for(CWnd* control=first->ribbon_.GetWindow(GW_CHILD);control;control=control->GetNextWindow())if(control->GetDlgCtrlID()==Color&&control->IsWindowVisible())customColorVisible=true;check(customColorVisible,"Draw tab exposes custom color picker alongside highlighter");
    first->OnToolCommand(EditorToolFirst+static_cast<UINT>(core::Tool::Highlight));CString opacity;first->opacity_.GetLBText(first->opacity_.GetCurSel(),opacity);check(first->style_.color==RGB(255,235,0)&&opacity==L"35%","highlighter starts yellow and displays its actual translucent opacity");
    first->OnPalette(PaletteFirst+6);Choice(first,first->opacity_,L"50%",OpacityChoice);Draw(first,core::Tool::Highlight,{25,165},{280,190});check(Wait(idle)&&first->document_.State().objects.back().color==RGB(30,160,75)&&first->document_.State().objects.back().opacity==128,"native highlighter preserves selected color and opacity");
    const auto* sample=first->image_.Row(175)+100*4;check(sample[1]>sample[2]&&sample[1]>sample[0]&&sample[0]>70,"green highlighter renders translucent pixels rather than opaque paint");
    first->OnToolCommand(EditorToolFirst+static_cast<UINT>(core::Tool::Rectangle));first->OnPalette(PaletteFirst+3);Draw(first,core::Tool::Rectangle,{15,15},{305,210});check(Wait(idle)&&first->document_.State().objects.back().color==RGB(240,40,40),"red frame remains separately editable");
    first->OnToolCommand(EditorToolFirst+static_cast<UINT>(core::Tool::Highlight));check(first->style_.color==RGB(30,160,75)&&first->style_.opacity==128,"switching to red frames does not lose remembered highlighter color");
    const auto colorTimer=::SetTimer(nullptr,0,70,[](HWND,UINT,UINT_PTR timer,DWORD){bool found=false;EnumThreadWindows(GetCurrentThreadId(),[](HWND window,LPARAM data)->BOOL{if(auto* color=dynamic_cast<CColorDialog*>(CWnd::FromHandlePermanent(window))){color->SetCurrentColor(RGB(110,50,220));color->PostMessage(WM_COMMAND,IDOK);*reinterpret_cast<bool*>(data)=true;return FALSE;}return TRUE;},reinterpret_cast<LPARAM>(&found));if(found)::KillTimer(nullptr,timer);});
    first->OnAction(Color);::KillTimer(nullptr,colorTimer);services::NeutralTestKeys();check(first->style_.color==RGB(110,50,220)&&first->palette_.color==RGB(110,50,220),"native custom color dialog applies non-palette highlighter color");Draw(first,core::Tool::Highlight,{25,195},{280,205});check(Wait(idle),"custom highlighter renders");
    first->OnToolCommand(EditorToolFirst+static_cast<UINT>(core::Tool::Text));Choice(first,first->fontSize_,L"36",FontSizeChoice);Draw(first,core::Tool::Text,{25,120},{290,165});first->text_.SetWindowText(L"Image A");first->text_.SetFocus();Key(first,'A');int selectedStart=0,selectedEnd=0;first->text_.GetSel(selectedStart,selectedEnd);check(selectedStart==0&&selectedEnd==7&&first->pixelSelection_.IsRectEmpty(),"Ctrl+A while entering text selects text instead of the canvas");Key(first,VK_RETURN);check(first->GetFocus()!=&first->text_,"committing inline text returns keyboard input away from the hidden edit control");check(Wait(idle)&&first->document_.State().objects.back().text==L"Image A"&&first->document_.State().objects.back().fontSize==36,"sized text is committed as an editable source annotation");
    first->OnToolCommand(EditorToolFirst+static_cast<UINT>(core::Tool::Step));Choice(first,first->fontSize_,L"16",FontSizeChoice);for(int n=0;n<10;++n)Draw(first,core::Tool::Step,{25+(n%5)*55,30+(n/5)*45},{25+(n%5)*55,30+(n/5)*45});
    bool numbers=true;int count=0;for(const auto& object:first->document_.State().objects)if(object.tool==core::Tool::Step)numbers=numbers&&object.number==++count;check(Wait(idle)&&numbers&&count==10,"native number stamps automatically progress from 1 through 10");
    const auto originalA=first->document_.State();
    CString error;core::Image stale;stale.Create(24,16);auto packet=services::PrepareClipboardImage(stale,error);check(packet&&services::PublishClipboardImage(*packet,first->m_hWnd,error),"known stale clipboard fixture published");
    check(Wait(idle),"source annotation ready");first->selected_=0;
    const auto state=first->document_.State();const auto revision=first->revision_,preview=first->previewGeneration_;first->activeAction_=0;
    first->job_.Start([state,revision,preview]{Sleep(200);EditorFrame::WorkResult result;result.action=0;result.revision=revision;result.preview=preview;services::RenderDocument(state,result.image,result.error);return result;});
    EditorWorkspace::Current()->Activate(first);Key(first,'A');Key(first,'C');check(first->pixelSelection_==CRect(0,0,320,220),"Ctrl+A selects the whole canvas immediately during background rendering");
    EditorWorkspace::Current()->Activate(second);Key(second,'V');check(!second->job_.Busy()&&second->document_.State().objects.empty(),"cross-document paste waits for the requested pending copy instead of reading stale clipboard");
    check(Wait(idle),"queued cross-document copy and paste finish");
    const auto& objects=second->document_.State().objects;check(objects.size()==1&&objects[0].asset&&objects[0].asset->width==320&&objects[0].asset->height==220,"fast A-to-B paste receives the complete composed source, not previous clipboard contents");
    log<<"RAM_REPRO paste_objects="<<objects.size();if(!objects.empty()&&objects[0].asset)log<<" size="<<objects[0].asset->width<<"x"<<objects[0].asset->height;log<<"\n";
    if(objects.size()==1&&objects[0].asset){const auto expected=first->image_.pixels;check(objects[0].asset->pixels==expected,"A-to-B asset retains background, text, frames, colors and all number stamps");}
    EditorWorkspace::Current()->Activate(second);second->ZoomTo(1);Draw(second,core::Tool::Select,{160,110},{300,200});check(Wait(idle)&&second->document_.State().objects.size()==1&&second->document_.State().objects[0].rect.left==140&&second->document_.State().objects[0].rect.top==90,"pasted complete image can be moved on B without moving the B background");
    Key(second,'A');Key(second,'C');EditorWorkspace::Current()->Activate(third);Key(third,'V');check(Wait(idle)&&third->document_.State().objects.size()==1&&third->document_.State().objects[0].asset&&third->document_.State().objects[0].asset->width==640&&third->document_.State().objects[0].asset->height==480,"B-to-C composition copies the whole B canvas with its positioned A image");
    if(!third->document_.State().objects.empty()&&third->document_.State().objects[0].asset)check(third->document_.State().objects[0].asset->pixels==second->image_.pixels,"C contains B's exact composed pixels");
    third->ZoomTo(1);Draw(third,core::Tool::Select,{320,240},{420,300});check(Wait(idle)&&third->document_.State().objects[0].rect.left==100&&third->document_.State().objects[0].rect.top==60,"composed B image can be independently positioned on C");
    third->offsetY_=std::max(0,720-third->canvas_.Height());third->ClampViewport();third->OnToolCommand(EditorToolFirst+static_cast<UINT>(core::Tool::Text));Choice(third,third->fontSize_,L"40",FontSizeChoice);Draw(third,core::Tool::Text,{30,600},{900,680});third->text_.SetWindowText(L"Detailed explanation on image C");Key(third,VK_RETURN);check(Wait(idle)&&third->document_.State().objects.size()==2&&third->document_.State().objects.back().fontSize==40,"C accepts detailed sized text after composing A and B");
    Key(third,'A');Key(third,'C');check(Wait(idle),"final complete C canvas copy finishes");core::Image external;auto read=std::async(std::launch::async,[&]{return services::ReadClipboardImage(third->m_hWnd,external,error);});Wait([&]{return read.wait_for(std::chrono::milliseconds(0))==std::future_status::ready;});check(read.get()&&external.width==1000&&external.height==720&&external.pixels==third->image_.pixels,"final external PNG clipboard contains the exact complete C canvas");
    check(EditorWorkspace::Current()->Pages().size()==3&&first->dirty_&&second->dirty_&&third->dirty_&&first->path_.IsEmpty()&&second->path_.IsEmpty()&&third->path_.IsEmpty()&&first->document_.State().base==originalA.base&&first->document_.State().objects.size()==originalA.objects.size(),"A B C stay unsaved in RAM with source annotations and independent dirty states");
    const auto before=third->document_.State().objects.size();const auto failed=services::BeginClipboardTransfer();services::CompleteClipboardTransfer(failed,false);Key(third,'V');check(Wait(idle)&&third->document_.State().objects.size()==before,"failed source copy never pastes stale clipboard contents");
    const auto pending=services::BeginClipboardTransfer();Key(third,'V');const auto newer=services::BeginClipboardTransfer();services::CompleteClipboardTransfer(newer,false);check(Wait(idle)&&third->document_.State().objects.size()==before&&services::InspectClipboardTransfer(pending)==services::ClipboardTransferState::Failed,"superseded pending copy cancels its waiting paste without modifying the document");
    const auto changed=services::BeginClipboardTransfer();const DWORD oldSequence=GetClipboardSequenceNumber();auto replacement=services::PrepareClipboardImage(stale,error);const bool replaced=replacement&&Wait([&]{return services::PublishClipboardImage(*replacement,third->m_hWnd,error);});log<<"CLIPBOARD_REPLACEMENT old="<<oldSequence<<" new="<<GetClipboardSequenceNumber()<<" published="<<replaced<<" error="<<CStringA(error).GetString()<<"\n";check(replaced&&!services::CanPublishClipboardTransfer(changed),"external clipboard change prevents an older background copy from overwriting newer contents");services::CompleteClipboardTransfer(changed,false);
    auto delayed=[&]{const auto current=first->document_.State();const auto rev=first->revision_,generation=first->previewGeneration_;first->activeAction_=0;first->job_.Start([current,rev,generation]{Sleep(150);EditorFrame::WorkResult result;result.action=0;result.revision=rev;result.preview=generation;services::RenderDocument(current,result.image,result.error);return result;});};
    delayed();Key(first,'C');const auto intervening=services::BeginClipboardTransfer();Key(first,'C');check(first->copyTicket_>intervening&&services::CanPublishClipboardTransfer(first->copyTicket_),"a newly repeated copy replaces the old queued intent without being mistaken for replay");check(Wait(idle)&&services::InspectClipboardTransfer(intervening)==services::ClipboardTransferState::Failed,"latest repeated copy completes and keeps the intervening older intent superseded");
    delayed();Key(first,'C');Key(third,'V');first->OnAction(ZoomFit);check(Wait(idle)&&!first->copyTicket_&&!third->pasteTicket_&&third->document_.State().objects.size()==before,"replacing a queued copy releases its waiting paste without stale insertion or stuck busy state");
    auto render=std::async(std::launch::async,[&]{return services::CaptureService::Save(external,(dir/L"ram-composition-final-evidence.png").c_str(),error);});check(render.get(),"explicit native test evidence written outside build, not an automatic user save");
    for(auto* page:{first,second,third}){page->dirty_=false;page->DestroyWindow();}services::PumpNativeTestMessages();
}
};
}
namespace sct::services {void RamCompositionChecks(const std::function<void(bool,const char*)>& check,std::ofstream& log,const std::filesystem::path& directory){ui::RamCompositionAccess::Run(check,log,directory);}}
